		if(combo == columnRslt_trd_unit_cd) return getRslt_trd_unit_cd(row, info);
		if(combo == columnRslt_re_arr_loc_cd) return getRslt_re_arr_loc_cd(row, info);
		if(combo == Rslt_re_arr_str_ln_p_PPanel.columnStrLn_str_ln_cd) return getRslt_re_arr_str_ln_p_PPanel_columnStrLn_str_ln_cd(row, info);
		if(combo == columnRslt_quality_typ) return getRslt_quality_typ(row, info);
		if(combo == columnRslt_gd_cd) return getRslt_gd_cd(row, info);
		if(combo == columnRslt_in_to_loc_cd) return getRslt_in_to_loc_cd(row, info);
		if(combo == Rslt_in_to_str_ln_p_PPanel.columnStrLn_str_ln_cd) return getRslt_in_to_str_ln_p_PPanel_columnStrLn_str_ln_cd(row, info);
		if(combo == Rslt_lot_no_p_PPanel.columnLotNo_lot_no) return getRslt_lot_no_p_PPanel_columnLotNo_lot_no(row, info);
		if(combo == Rslt_lot_no_p_PPanel.columnLotNo_sublot_no) return getRslt_lot_no_p_PPanel_columnLotNo_sublot_no(row, info);
		if(combo == Rslt_ver_no_p_PPanel.columnVerNo_ver_no) return getRslt_ver_no_p_PPanel_columnVerNo_ver_no(row, info);
		if(combo == columnRslt_trd_cur_cd) return getRslt_trd_cur_cd(row, info);
		if(combo == Rslt_trd_upri_amt_p_PPanel.columnTrdUpriAmt_tax_cd) return getRslt_trd_upri_amt_p_PPanel_columnTrdUpriAmt_tax_cd(row, info);
		if(combo == Rslt_trd_upri_amt_p_PPanel.columnTrdUpriAmt_dscnt_rsn_cd) return getRslt_trd_upri_amt_p_PPanel_columnTrdUpriAmt_dscnt_rsn_cd(row, info);
		if(combo == columnRslt_purc_rsn_cd) return getRslt_purc_rsn_cd(row, info);
		if(combo == columnRslt_stk_insp_typ) return getRslt_stk_insp_typ(row, info);
		if(combo == columnRslt_ap_dpt_cd) return getRslt_ap_dpt_cd(row, info);
