		if(combo == Rslt_usr_dpt_p_PPanel.columnUsrDpt_dpt_cd) return getRslt_usr_dpt_p_PPanel_columnUsrDpt_dpt_cd(row, info);
		if(combo == Rslt_bditm_p_PPanel.columnBdItem_bd_dpt_cd) return getRslt_bditm_p_PPanel_columnBdItem_bd_dpt_cd(row, info);
